from pathlib import Path; import json,subprocess; m=json.loads(Path("lake-manifest.json").read_text()); print("root:",m["name"]); print("project toolchain:",Path("lean-toolchain").read_text().strip());
for p in m["packages"]:
 d=Path(".lake/packages")/p["name"]; head=subprocess.check_output(["git","-C",str(d),"rev-parse","HEAD"],text=True).strip(); assert head==p["rev"],p["name"]; print(p["name"],"inputRev=",p.get("inputRev"),"resolved=",p["rev"],"checkout=",head);
p=Path(".lake/packages/mathlib"); tag=subprocess.check_output(["git","-C",str(p),"rev-parse","v4.31.0^{commit}"],text=True).strip(); assert tag=="fabf563a7c95a166b8d7b6efca11c8b4dc9d911f"; assert (p/"lean-toolchain").read_text()==Path("lean-toolchain").read_text(); print("mathlib v4.31.0 tag and toolchain match")

